async function revalidateKeptOlderMessages(kept: ChatMessage[]): Promise<ChatMessage[]> {
  const ids = kept.map((m) => String(m.id || '')).filter(Boolean);
  if (ids.length === 0) return kept;
  const { data, error } = await selectChatMessagesWithFallback<ChatMessage[]>(
    ({ omittedColumns, selectClause }) => {
      let q = db.from('messages').select(selectClause).in('id', ids);
      if (!omittedColumns.has('is_deleted')) q = q.eq('is_deleted', false);
      return q as PromiseLike<{ data: ChatMessage[] | null; error: unknown }>;
    },
  );
  if (error || !Array.isArray(data)) return kept;
  const fresh = new Map(data.map((row) => [String(row.id || ''), row] as const));
  return kept.reduce<ChatMessage[]>((acc, local) => {
    const row = fresh.get(String(local.id || ''));
    if (!row) return acc;                    // 삭제됨 → 제거
    acc.push({ ...local, ...row });          // 수정 반영. reactions 는 row 에 없어 보존된다
    return acc;
  }, []);
}

