```ts
/**
 * 200 인데 본문에 개별 실패가 담긴 크론을 실패로 판정한다.
 * bec2a511 이 배치 전체 중단을 막으면서, 실패를 알려 주던 유일한 신호(500→관리자 알림)도 같이 없앴다.
 * **개수 필드(failed/skipped)는 보지 않는다** — chat-push-dispatch 의 failed 는 만료 구독 때문에 상시 0이 아니다.
 */
function detectCronSoftFailure(bodyText: string): string | null {
  let parsed: unknown;
  try { parsed = JSON.parse(bodyText); } catch { return null; }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const body = parsed as Record<string, unknown>;

  const parts: string[] = [];
  if (body.ok === false) parts.push(`ok=false: ${String(body.error ?? '')}`);

  for (const [key, value] of Object.entries(body)) {
    // failures / errors / balanceErrors …
    if ((key === 'failures' || key === 'errors' || /Errors$/.test(key)) && Array.isArray(value) && value.length > 0) {
      parts.push(`${key}(${value.length})=${JSON.stringify(value).slice(0, 300)}`);
    }
    // licenseError / contractError / retentionError / inappNotificationsError / notificationsError …
    if (/Error$/.test(key) && typeof value === 'string' && value.trim()) {
      parts.push(`${key}=${value.slice(0, 300)}`);
    }
  }

  return parts.length > 0 ? parts.join(' | ') : null;
}
```

